return ['domain'=>NULL,'plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','language'=>'sr_RS','project-id-version'=>'Babilim 1.0.0','pot-creation-date'=>'2026-10-31T05:53:32+00:00','po-revision-date'=>'2026-10-31T05:53:32+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Попуњава преводе који недостају за додатке и теме већ инсталиране на вашем сајту.','Translations'=>'Преводи','Babilim Settings'=>'Babilim подешавања','Settings'=>'Подешавања','You are not allowed to do this.'=>'Није вам дозвољено да то урадите.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Изаберите мање компоненти: највише %1$d операција по покретању (изабрали сте %2$d).','That component is not installed on this site, so a translation cannot be requested for it.'=>'Та компонента није инсталирана на овом сајту, па се за њу не може затражити превод.','Already installed.'=>'Већ је инсталирано.','Downloaded and installed.'=>'Преузето и инсталирано.','Babilim has not been enabled for this site yet.'=>'Babilim још није омогућен за овај сајт.','No build is available to download for this locale.'=>'Нема доступне верзије за преузимање за овај језик.','Rolled back to the previous build.'=>'Враћено на претходну верзију.','Rolled back and reported.'=>'Враћено и пријављено.','Rolled back, but the report could not be sent: %s'=>'Враћено на претходну верзију, али извештај није могао бити послат: %s','Removed.'=>'Уклоњено.','Translation requested.'=>'Превод је затражен.','This component was already uploaded. Babilim is checking it now.'=>'Ова компонента је већ отпремљена. Babilim је сада проверава.','Upload cancelled.'=>'Отпремање је отказано.','Upload complete — translation requested.'=>'Отпремање је завршено — превод је затражен.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Ова компонента не наводи број верзије, па се за њу не може затражити превод.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Број верзије ове компоненте је дужи од %d знакова, што Babilim не може да обради, па се за њу не може затражити превод.','A translation cannot be requested for that locale on this site right now.'=>'Превод за тај језик тренутно се не може затражити на овом сајту.','Thank you. Your report was sent.'=>'Хвала. Ваш извештај је послат.','This report does not name a valid plugin or theme and locale.'=>'Овај извештај не наводи исправан додатак или тему и језик.','Please choose a category for this report.'=>'Изаберите категорију за овај извештај.','This report is missing a valid build to report against.'=>'Овом извештају недостаје исправна верзија на коју се односи.','This build is not one this site currently knows about for this component/locale.'=>'Овај сајт тренутно не познаје ову верзију за ову компоненту/језик.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Поље „%1$s“ је предугачко: има %2$d знакова, а ограничење је %3$d. Ништа није послато; скратите га и покушајте поново.','Original string'=>'Изворна ниска','String context'=>'Контекст стринга','Current translation'=>'Тренутни превод','Suggested translation'=>'Предложени превод','Note (optional)'=>'Напомена (необавезно)','Where you saw this (optional)'=>'Где сте ово видели (необавезно)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Babilim синхронизација је привремено одложена од стране сервиса (ограничење броја захтева); покушаће поново након %s.','That is not a valid WordPress locale code. Nothing was saved.'=>'То није исправан Вордпрес код језика. Ништа није сачувано.','Settings saved.'=>'Подешавања су сачувана.','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Ако је ово укључено, деинсталација такође брише идентитет овог сајта. Плаћена лиценца везана за овај сајт након тога се не може аутоматски вратити; морали бисте да контактирате Babilim подршку на %s да бисте је повратили.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim је подешен да избрише идентитет овог сајта када се додатак обрише. Плаћена лиценца везана за овај сајт тада се не би могла аутоматски вратити; морали бисте да контактирате Babilim подршку на %s. Да бисте задржали идентитет, притисните Откажи, уклоните ознаку са „Избриши све Babilim податке при деинсталацији“ у Babilim подешавањима и поново деактивирајте. Деактивирати свакако?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d сајт у овој мрежи је подешен да избрише свој Babilim идентитет када се додатак обрише. Плаћена лиценца везана за тај сајт тада се не би могла аутоматски вратити; морали бисте да контактирате Babilim подршку на %2$s. Да бисте задржали идентитет, притисните Откажи, уклоните ознаку са „Избриши све Babilim податке при деинсталацији“ у Babilim подешавањима тог сајта и поново деактивирајте. Деактивирати свакако?' . "\0" . '%1$d сајта у овој мрежи су подешена да избришу свој Babilim идентитет када се додатак обрише. Плаћена лиценца везана за те сајтове тада се не би могла аутоматски вратити; морали бисте да контактирате Babilim подршку на %2$s. Да бисте задржали идентитете, притисните Откажи, уклоните ознаку са „Избриши све Babilim податке при деинсталацији“ у Babilim подешавањима сваког сајта и поново деактивирајте. Деактивирати свакако?' . "\0" . '%1$d сајтова у овој мрежи је подешено да избришу свој Babilim идентитет када се додатак обрише. Плаћена лиценца везана за те сајтове тада се не би могла аутоматски вратити; морали бисте да контактирате Babilim подршку на %2$s. Да бисте задржали идентитете, притисните Откажи, уклоните ознаку са „Избриши све Babilim податке при деинсталацији“ у Babilim подешавањима сваког сајта и поново деактивирајте. Деактивирати свакако?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Ова мрежа има превише сајтова да би се проверавали један по један, а неки од њих можда су подешени да избришу свој Babilim идентитет када се додатак обрише. Плаћена лиценца везана за такав сајт тада се не би могла аутоматски вратити; морали бисте да контактирате Babilim подршку на %s. Да бисте задржали идентитете, притисните Откажи, уклоните ознаку са „Избриши све Babilim податке при деинсталацији“ у Babilim подешавањима сваког сајта и поново деактивирајте. Деактивирати свакако?','Open Babilim settings'=>'Отвори Babilim подешавања','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim није могао да верификује овај сајт, па се ништа не преузима нити инсталира.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Сервис није могао да допре до вашег сајта. Вероватно захтев блокира заштитни зид, безбедносни додатак или правило хостинга; дозволите захтеве ка /wp-json/babilim/v1/challenge.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Ваш сајт је предуго одговарао. Покушајте поново касније и проверите да хостинг није превише спор или преоптерећен.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Ваш сајт је одговорио, али не оним што се очекивало. REST API можда преписује други додатак, или је та крајња тачка кеширана; изузмите /wp-json/babilim/v1/challenge из кеширања и преписивања.','Please check that your site can be reached from the internet, then try again.'=>'Проверите да ли је ваш сајт доступан са интернета, а затим покушајте поново.','Re-verify'=>'Поново верификуј','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Овај сајт прелази величину коју сервис прихвата у једној синхронизацији, па су неке ставке изостављене: %1$d компоненти и %2$d језичких варијанти.','This site is verified.'=>'Овај сајт је верификован.','Registration restarted.'=>'Регистрација је поново покренута.','Sync complete.'=>'Синхронизација је завршена.','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim омогућава и проверава овај сајт… Поново учитајте страницу или сачекајте да се заказана провера заврши.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim није могао да заврши омогућавање (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'Хост који опslужује само један PHP захтев истовремено не може да заврши овај корак.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim је омогућен: овај сајт је верификован и пронађена је %d компонента.' . "\0" . 'Babilim је омогућен: овај сајт је верификован и пронађене су %d компоненте.' . "\0" . 'Babilim је омогућен: овај сајт је верификован и пронађено је %d компоненти.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim је онемогућен. Више се ништа не шаље; већ инсталирани преводи настављају да раде.','Supplementary translation index rebuilt.'=>'Допунски индекс превода је поново изграђен.','Sweep complete: %d file deleted.'=>'Чишћење је завршено: %d датотека је избрисана.' . "\0" . 'Чишћење је завршено: %d датотеке су избрисане.' . "\0" . 'Чишћење је завршено: %d датотека је избрисано.','Removed %d installed component.'=>'Уклоњена је %d инсталирана компонента.' . "\0" . 'Уклоњене су %d инсталиране компоненте.' . "\0" . 'Уклоњено је %d инсталираних компоненти.','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Аутоматске инсталације су сада искључене; поново их укључите у подешавањима ако желите.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim проналази додатке и теме на овом сајту који немају превод за ваш језик и инсталира по један за сваки.','Languages found on this site: %s.'=>'Језици пронађени на овом сајту: %s.','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'Доступни преводи могу се инсталирати једним кликом, а они који недостају могу се затражити. Након тога се нови преводи и ажурирања инсталирају аутоматски (у бесплатном плану само за додатке и теме који већ користе бесплатно место).','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'Бесплатни план покрива ограничен број додатака и тема; ваша тачна квота приказана је у Подешавањима након што омогућите Babilim.','What is sent when you enable Babilim'=>'Шта се шаље када омогућите Babilim','Enabling…'=>'Омогућавање…','Enable Babilim'=>'Омогући Babilim','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Кликом на Омогући пристајете да информације наведене изнад пошаљете сервису Babilim.','Check again now'=>'Провери поново сада','Babilim installed %d translation automatically since your last visit.'=>'Babilim је аутоматски инсталирао %d превод од ваше последње посете.' . "\0" . 'Babilim је аутоматски инсталирао %d превода од ваше последње посете.' . "\0" . 'Babilim је аутоматски инсталирао %d превода од ваше последње посете.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim омогућава и проверава овај сајт… (последњи покушај: %s)','Check again'=>'Провери поново','No components synced yet.'=>'Још ниједна компонента није синхронизована.','%d succeeded'=>'%d успешно' . "\0" . '%d успешно' . "\0" . '%d успешно','%d skipped'=>'%d прескочено' . "\0" . '%d прескочено' . "\0" . '%d прескочено','%d failed'=>'%d неуспешно' . "\0" . '%d неуспешно' . "\0" . '%d неуспешно','%d not yet tried'=>'%d још није покушано' . "\0" . '%d још није покушано' . "\0" . '%d још није покушано','%1$s nothing to do.'=>'%1$s нема шта да се уради.','%1$s %2$s.'=>'%1$s %2$s.','Bulk download:'=>'Групно преузимање:','Bulk update:'=>'Групно ажурирање:','Bulk request:'=>'Групни захтев:','per day'=>'дневно','Wrong meaning'=>'Погрешно значење','Wrong term'=>'Погрешан термин','Broken placeholder'=>'Покварен чувар места','Wrong for this context'=>'Погрешно за овај контекст','Wrong plural form'=>'Погрешан облик множине','Negation reversed'=>'Негација је обрнута','Translation does not load'=>'Превод се не учитава','problem report categoryOther'=>'Остало','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'Настављање…','Continue next batch (%d left)'=>'Настави са следећом групом (преостало: %d)','Search components'=>'Претражи компоненте','These are the languages this site uses. You can change them in %s.'=>'Ово су језици које овај сајт користи. Можете их променити у %s.','Upload this component?'=>'Отпреми ову компоненту?','There is no upload waiting for confirmation.'=>'Нема отпремања које чека потврду.','Back'=>'Назад','To translate this component, Babilim needs its source.'=>'За превођење ове компоненте Babilim-у је потребан њен изворни код.','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'Цео директоријум додатка или теме %1$s (верзија %2$s) биће отпремљен на Babilim.','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'Ако тај директоријум садржи кључеве, дневнике или податке о клијентима, и они ће бити отпремљени. Услуга уклања уобичајене осетљиве датотеке (конфигурацију, окружење, извозе базе података, дневнике, кључеве), али не може да гарантује да проналази све.','The upload is kept until you ask Babilim to delete it.'=>'Отпремљени садржај се чува док не затражите од Babilim-а да га избрише.','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Чува га добављач хостинга услуге, а AI модели га обрађују да би направили превод.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Оригинални текст и преводи направљени на основу њега биће дати другим сајтовима који инсталирају исту верзију.','By continuing you confirm that you have the right to upload this component.'=>'Настављањем потврђујете да имате право да отпремите ову компоненту.','Upload and request'=>'Отпреми и затражи','Uploading…'=>'Отпремање…','Cancel'=>'Откажи','Uploading'=>'Отпремање','There is no upload in progress.'=>'Отпремање није у току.','Uploading part %1$d of %2$d…'=>'Отпремање дела %1$d од %2$d…','Continue'=>'Настави','Confirm'=>'Потврди','Remove'=>'Уклони','Roll back'=>'Врати на претходно','Nothing to confirm.'=>'Нема шта да се потврди.','Choose a language'=>'Изаберите језик','Roll back and report'=>'Врати на претходно и пријави','Report a problem'=>'Пријави проблем','Nothing to choose.'=>'Нема шта да се изабере.','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Изаберите језик.','Supplementary translations'=>'Додатни преводи','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Допринос сваке компоненте заједничкој допуни подразумеваног домена сваког језика.','Component'=>'Компонента','Language'=>'Језик','Included in index'=>'Укључено у индекс','Entries'=>'Уноси','Conflicting keys'=>'Конфликтни кључеви','Yes'=>'Да','No — component inactive'=>'Не — компонента је неактивна','No — installed version differs from the active one'=>'Не — инсталирана верзија се разликује од активне','No — component removed'=>'Не — компонента је уклоњена','No'=>'Не','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Ово може да уради само администратор мреже, јер се мењају датотеке превода које деле сви сајтови у овој мрежи.','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim није могао да заврши проверу овог сајта (услуга није могла да му приступи). Регистрација је паузирана.','This site already has an active registration that can no longer be recovered automatically.'=>'Овај сајт већ има активну регистрацију која се више не може аутоматски опоравити.','Restart registration'=>'Поново покрени регистрацију','Babilim settings'=>'Babilim подешавања','General'=>'Опште','Advanced'=>'Напредно','Languages'=>'Језици','Automatic installs'=>'Аутоматске инсталације','Install available translations automatically'=>'Аутоматски инсталирај доступне преводе','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'У бесплатном плану аутоматски се инсталирају само компоненте које већ користе једно од ваших бесплатних места, тако да се ново место не заузима.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Овај сајт је део мултисајт мреже, која не инсталира нове преводе аутоматски. Већ инсталирани преводи се и даље ажурирају.','Custom overrides'=>'Сопствена замењивања','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Задржи моја сопствена замењивања превода при брисању свега или деинсталацији овог додатка.','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Датотеке превода које ставите у %s увек имају приоритет над Babilim датотекама. Задржавају се осим ако ово не искључите.','Uninstall'=>'Деинсталација','Delete all Babilim data on uninstall'=>'Избриши све Babilim податке при деинсталацији','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Подразумевано искључено: брисање додатка задржава идентитет овог сајта, па га поновна инсталација може поново користити.','Account'=>'Налог','Save changes'=>'Сачувај промене','Disable Babilim'=>'Искључи Babilim','Installed translations are kept, but no further checks or downloads will run.'=>'Инсталирани преводи се задржавају, али се више неће вршити провере нити преузимања.','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Искључити Babilim? Инсталирани преводи се задржавају, али се више неће вршити провере нити преузимања.','This site is not registered with Babilim yet.'=>'Овај сајт још није регистрован код Babilim-а.','This site is already licensed. Reload the page.'=>'Овај сајт је већ лиценциран. Поново учитајте страницу.','Checkout is not available for this site right now.'=>'Наплата тренутно није доступна за овај сајт.','Could not start checkout: %s'=>'Није могуће покренути наплату: %s','Babilim is not enabled.'=>'Babilim није омогућен.','Not registered yet'=>'Још није регистровано','Not verified'=>'Није верификовано','Verified'=>'Верификовано','Status'=>'Статус','Licensed'=>'Лиценцирано','Partner'=>'Партнер','Free'=>'Бесплатно','License'=>'Лиценца','Upgrade this site'=>'Надогради овај сајт','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Једнократна куповина за овај сајт: %1$s %2$s. Укључује сва будућа ажурирања превода. Плаћањем управља Paddle у новој картици.','This issues a new restore code and the previous one stops working. Continue?'=>'Ово издаје нови код за враћање, а претходни престаје да важи. Желите ли да наставите?','Show a new restore code'=>'Прикажи нови код за враћање','rc_…'=>'rc_…','Restore code'=>'Код за враћање','Restore purchase'=>'Врати куповину','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Већ сте купили лиценцу за овај домен? Унесите код за враћање који сте добили при куповини.','That does not look like a restore code.'=>'Ово не изгледа као код за враћање.','This restore code was not recognised for this site.'=>'Овај код за враћање није препознат за овај сајт.','Too many attempts. Try again tomorrow.'=>'Превише покушаја. Покушајте поново сутра.','This site must be verified first.'=>'Овај сајт прво мора бити верификован.','Could not restore the purchase: %s'=>'Није могуће вратити куповину: %s','Purchase restored. This site is now licensed.'=>'Куповина је враћена. Овај сајт је сада лиценциран.','This site has no purchase to show a code for.'=>'Овај сајт нема куповину за коју би се приказао код.','Could not show a new restore code: %s'=>'Није могуће приказати нови код за враћање: %s','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Ваш нови код за враћање: %s. Чувајте га на сигурном месту — претходни код више не важи.','What is sent when Babilim checks this site'=>'Шта се шаље када Babilim проверава овај сајт','(detected)'=>'(откривено)','No language is managed yet.'=>'Још ниједан језик није под управом.','Babilim adds translations for every language checked here.'=>'Babilim додаје преводе за сваки овде означен језик.','Add another language'=>'Додај још један језик','Choose a language…'=>'Изаберите језик…','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Није могуће учитати потпуну листу језичких поставки WordPress.org са сервиса, па тренутно није могуће додати још неки језик.','Theme'=>'Тема','Plugin'=>'Додатак','Free quota'=>'Бесплатна квота','Downloads: %1$d/%2$d (%3$s)'=>'Преузимања: %1$d/%2$d (%3$s)','Supplementary translation index'=>'Индекс додатних превода','Built'=>'Изграђено','Included'=>'Укључено','Excluded'=>'Изузето','Already in WordPress core'=>'Већ у језгру Вордпреса','Supplementary translation maintenance'=>'Одржавање допунских превода','Maintenance status is not available right now.'=>'Статус одржавања тренутно није доступан.','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Чишћење је паузирано у %1$s: %2$s. Ништа није обрисано.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Последње чишћење у %1$s: ново означених: %2$d, обрисаних датотека: %3$d, уклоњених записа: %4$d.','No cleanup has run yet.'=>'Чишћење још није покренуто.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Упис у индекс превода је у сукобу са другим захтевом на %1$s (%2$s) и није примењен; задржана је најновија верзија.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Упис у индекс превода на %1$s (%2$s) није могао бити завршен и није примењен (%3$s).','Maintenance'=>'Одржавање','Rebuild index now'=>'Обнови индекс сада','Sweep now'=>'Очисти сада','Danger zone'=>'Опасна зона','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Уклања сваку датотеку за Језик коју је Babilim инсталирао за сваки додатак и тему на овом сајту.','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Уклонити све што је Babilim инсталирао? Ово брише сваку датотеку језика коју је инсталирао за сваки додатак и сваку тему на овом сајту.','Remove everything Babilim installed'=>'Уклони све што је Babilim инсталирао','This string is too long to be sent as a report, so no report form is offered for it.'=>'Овај низ је предугачак да би се послао као извештај, па се за њега не нуди образац за извештај.','Category'=>'Категорија','Choose a category…'=>'Изаберите категорију…','Roll back and send report'=>'Врати и пошаљи извештај','Send report'=>'Пошаљи извештај','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Аутор је део текста ове компоненте уписао директно у код, па тај текст не може да се преведе помоћу пакета за језик.','WordPress.org'=>'WordPress.org','Bundled with the theme'=>'Укључено уз тему','Bundled with the plugin'=>'Укључено уз додатак','Upload was not accepted'=>'Отпремање није прихваћено','Upload expired before it finished'=>'Отпремање је истекло пре завршетка','No translation'=>'Нема превода','Upload in progress — continue or cancel'=>'Отпремање је у току — наставите или откажите','Scheduled, waiting to be processed'=>'Заказано, чека на обраду','Translating…'=>'Превођење…','Translation failed'=>'Превод није успео','Free quota used'=>'Бесплатна квота искоришћена','Needs a paid license'=>'Потребна је плаћена лиценца','Not supported'=>'Није подржано','Status unknown'=>'Статус је непознат','translation statusInstalled'=>'Инсталирано','Update available'=>'Доступно ажурирање','Removed after a failed integrity check'=>'Уклоњено после неуспеле провере интегритета','Installed · built for %s, new version scheduled'=>'Инсталирано · направљено за %s, нова верзија је заказана','Installed · built for a different version, new version scheduled'=>'Инсталирано · направљено за другу верзију, нова верзија је заказана','Installed · built for %s, translating the new version…'=>'Инсталирано · направљено за %s, превођење нове верзије…','Installed · built for a different version, translating the new version…'=>'Инсталирано · направљено за другу верзију, превођење нове верзије…','Installed · built for %1$s, this site has %2$s'=>'Инсталирано · направљено за %1$s, овај сајт има %2$s','Installed · built for %s'=>'Инсталирано · направљено за %s','Installed · built for a different version'=>'Инсталирано · направљено за другу верзију','Installed · built for %s, new version failed'=>'Инсталирано · направљено за %s, нова верзија није успела','Installed · built for a different version, new version failed'=>'Инсталирано · направљено за другу верзију, нова верзија није успела','Installed · built for %s, new version needs a paid license'=>'Инсталирано · изграђено за %s, нова верзија захтева плаћену лиценцу','Installed · built for a different version, new version needs a paid license'=>'Инсталирано · изграђено за другу верзију, нова верзија захтева плаћену лиценцу','Installed · built for %s, free quota used'=>'Инсталирано · изграђено за %s, бесплатна квота искоришћена','Installed · built for a different version, free quota used'=>'Инсталирано · изграђено за другу верзију, бесплатна квота искоришћена','translation statusAvailable'=>'Доступно','Installed · %s'=>'Инсталирано · %s','Available · %s'=>'Доступно · %s','Update'=>'Ажурирај','Download'=>'Преузми','Updating…'=>'Ажурирање…','Downloading…'=>'Преузимање…','Retry request'=>'Покушај захтев поново','Request newer translation'=>'Затражи новији превод','Request translation'=>'Затражи превод','Requesting…'=>'Захтевање…','Requesting a translation uses one of your free slots, unless this component already uses one. A failed translation does not give the slot back.'=>'Захтевање превода користи једно од ваших бесплатних места, осим ако ова компонента већ користи једно. Неуспео превод не враћа место.','If this component does not use one of your free slots yet, requesting a translation uses one. A failed translation does not give the slot back. Continue?'=>'Ако ова компонента још не користи једно од ваших бесплатних места, захтевање превода користи једно. Неуспео превод не враћа место. Наставити?','No plugins or themes found.'=>'Нису пронађени додаци ни теме.','Clear filters'=>'Обриши филтере','No components match these filters. %s'=>'Ниједна компонента не одговара овим филтерима. %s','Select all'=>'Изабери све','All'=>'Све','Available'=>'Доступно','Updates'=>'Ажурирања','Requestable'=>'Може се захтевати','Installed'=>'Инсталирано','Plugins'=>'Додаци','Themes'=>'Теме','All languages'=>'Сви језици','%d to install'=>'%d за инсталацију' . "\0" . '%d за инсталацију' . "\0" . '%d за инсталацију','Language:'=>'Језик:','Bulk actions apply to every matching language of each selected component.'=>'Групне радње се примењују на сваки одговарајући језик сваке изабране компоненте.','Bulk actions apply only to the selected language of each selected component.'=>'Групне радње се примењују само на изабрани језик сваке изабране компоненте.','Version %s'=>'Верзија %s','Theme · %s'=>'Тема · %s','Plugin · %s'=>'Додатак · %s','Remove the %2$s translation of %1$s from this site?'=>'Уклонити %2$s превод за %1$s са овог сајта?','Roll back the %2$s translation of %1$s to the previous build?'=>'Вратити превод %2$s за %1$s на претходну верзију изградње?','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','The registration challenge is not in the expected form.'=>'Изазов за регистрацију није у очекиваном облику.','That is not a valid build identifier.'=>'То није важећи идентификатор верзије изградње.','Refusing to write outside the Babilim language-file directory.'=>'Одбијено је писање изван директоријума језичких датотека Babilim.','Could not write the downloaded package to disk.'=>'Преузети пакет није могао да се упише на диск.','Unexpected HTTP %d response.'=>'Неочекиван HTTP одговор %d.','This site\'s URL, so the service can verify you own it.'=>'URL овог сајта, да би услуга могла да потврди да сте његов власник.','Your WordPress version, to serve compatible translation files.'=>'Ваша верзија Вордпреса, ради испоруке компатибилних датотека превода.','Your PHP version, for compatibility.'=>'Ваша верзија PHP-а, ради компатибилности.','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Верзија самог овог додатка, да би вас услуга могла упозорити да га ажурирате ако је престар за комуникацију.','This site\'s configured locale.'=>'Подешени локалитет овог сајта.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Сваки језик који се користи на овом сајту (језик сајта, инсталирани језички пакети, језици корисника и сви које ручно додате). Ниједан језик се не третира другачије од другог.','(a public key generated for this site)'=>'(јавни кључ генерисан за овај сајт)','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Јавни кључ инсталације овог сајта, који служи као доказ да захтеви заиста потичу са овог сајта. Шаље се само јавни део.','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Сваки инсталирани додатак или тема: његова кратка ознака (slug), верзија, текстуални домени, податак о томе да ли је доступан на WordPress.org, језичке поставке за које садржи преводе и језичке поставке за које сте већ инсталирали Babilim превод.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: that component\'s entire directory, as a zip.'=>'Само када потврдите отпремање за додатак или тему који нису на WordPress.org: цео директоријум те компоненте, као zip.','(generic codes and coordinates only)'=>'(само опште шифре и координате)','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'До 20 дијагностичких догађаја на чекању (нпр. датотека која није прошла проверу интегритета), при чему сваки садржи само кôд, компоненту и језичку поставку, а никада садржај стрингова или преведени текст.','Unsafe locale: %s'=>'Небезбедна ознака језичке поставке: %s','Manifest unavailable: %s'=>'Манифест није доступан: %s','Could not determine active components; the existing merged index was left unchanged.'=>'Није могуће утврдити активне компоненте; постојећи спојени индекс је остављен непромењен.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Није могуће утврдити инсталиране додатке/теме; чишћење је прескочено, ништа није обрисано.','Sweep aborted without orphaning anything: %s.'=>'Чишћење је прекинуто без остављања иједног сирочета: %s.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Чишћење је покренуто, али неке његове промене није било могуће записати у индекс превода; следеће чишћење ће их поново покушати.','component kind in the sweep brake messagetheme'=>'тема','component kind in the sweep brake messageplugin'=>'додатак','it would orphan every managed %1$s component (%2$d of %2$d)'=>'створило би сирочад од свих управљаних компоненти врсте %1$s (%2$d од %2$d)','it would orphan %1$d of %2$d managed components (more than half)'=>'створило би сирочад од %1$d од %2$d управљаних компоненти (више од половине)','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Спојени индекс за „%s“ је поново изграђен, али индекс превода није могао да га забележи; следећа поновна изградња ће покушати поново.','Could not write the staged merged index.'=>'Није могуће записати припремљени обједињени индекс.','Re-parsed entry count did not match the built index.'=>'Број уноса поново обрађеног индекса не одговара изграђеном индексу.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Није могуће поставити обједињени индекс за „%s“ на место; претходни индекс који је био у употреби (ако га је било) уклоњен је уместо да буде остављен напола ажуриран. Допуна подразумеваног домена није доступна за ову језичку поставку до следеће успешне поновне изградње.','Could not open zip: %s'=>'Није могуће отворити zip: %s','Zip has no manifest.json.'=>'Zip нема manifest.json.','manifest.json in the zip is not valid JSON.'=>'manifest.json у zip-у није исправан JSON.','manifest.json\'s \'%s\' does not match the expected value.'=>'Поље „%s“ у датотеци manifest.json не одговара очекиваној вредности.','Another installation is running; try again in a moment.'=>'Друга инсталација је у току; покушајте поново за тренутак.','Not a valid server_build_id: %s'=>'Није важећи server_build_id: %s','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Врста манифеста пакета „%1$s“ не одговара захтеваној врсти „%2$s“.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Текстуални домен пакета „%1$s“ не одговара копији компоненте на овом сајту („%2$s“), па није инсталиран.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Наведени домен „%1$s“ не одговара ни сопственом слагу манифеста пакета „%2$s“ ни његовом text_domain „%3$s“.','Unsafe slug: %s'=>'Небезбедан слаг: %s','Unsafe text_domain: %s'=>'Небезбедан text_domain: %s','The package has no %s for its own text domain.'=>'Пакет нема %s за сопствени текстуални домен.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json недостаје или има неважеће поље „%s“.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json недостаје или има неважеће поље „entries“.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json недостаје или има неважеће поље „files“.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json недостаје или има неважеће поље „extra_domains“.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json недостаје или има неважеће поље „build_no“.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'Поље „server_build_id“ у датотеци manifest.json није важећи ИД изградње.','manifest.json\'s \'contract\' is not a valid version string.'=>'Поље „contract“ у датотеци manifest.json није важећи низ верзије.','manifest.json\'s \'status\' must be \'published\'.'=>'Поље „status“ у датотеци manifest.json мора бити „published“.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'Поље „kind“ у датотеци manifest.json мора бити „plugin“ или „theme“.','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json има неважеће поље „default_domain_entries“.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json има неважеће поље „default_domain_files“.','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest недостаје или има неважеће поље „%s“.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'Поље „server_build_id“ у expected_manifest није важећи ИД изградње.','No record for %s'=>'Нема записа за %s','One or more served files no longer match the manifest.'=>'Једна или више послужених датотека више не одговара манифесту.','No previous build to roll back to.'=>'Нема претходне изградње на коју би се могло вратити.','The change could not be recorded in the translation index; please try again.'=>'Промена није могла бити записана у индекс превода; покушајте поново.','Unknown kind: %s'=>'Непозната врста: %s','Unsafe domain: %s'=>'Небезбедан домен: %s','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Текстуални домен „%1$s“ (%2$s) већ се служи за другу инсталирану компоненту (%3$s); ништа није инсталирано.','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Враћање на претходно стање би преписало „%1$s“ (%2$s), која се сада служи за другу инсталирану компоненту (%3$s); ништа није промењено.','Zip is missing expected file: %s'=>'У zip недостаје очекивана датотека: %s','sha256 mismatch for %s'=>'Неусклађеност sha256 суме за %s','The package declares no main translation file.'=>'Пакет не декларише главну датотеку превода.','Zip is missing expected default file: %s'=>'У zip недостаје очекивана подразумевана датотека: %s','sha256 mismatch for default/%s'=>'Неусклађеност sha256 суме за default/%s','Could not stage %s'=>'Није могуће припремити %s','Could not stage default/%s'=>'Није могуће припремити default/%s','Entry count mismatch for %s'=>'Број уноса се не поклапа за %s','Could not verify entry count for %s'=>'Није могуће проверити број уноса за %s','l10n.php entry count mismatch for %s'=>'Број уноса у l10n.php датотеци не одговара за %s','Default supplement entry count mismatch.'=>'Број уноса у допуни за домен default се не поклапа.','The package produced no servable main translation file.'=>'Пакет није произвео употребљиву главну датотеку превода.','Could not prepare %s for rollback.'=>'Није могуће припремити %s за враћање на претходно стање.','Could not back up %s before replacing it.'=>'Није могуће направити резервну копију %s пре замене.','Could not move %s into place.'=>'Није могуће преместити %s на место.','Could not read %s back after moving it into place.'=>'Није могуће поново прочитати %s након премештања на место.','English (United States)'=>'Енглески (Сједињене Америчке Државе)','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest није доступан: %s','could not read _manifest.json: %s'=>'није могуће прочитати _manifest.json: %s','failed to parse _manifest.json: %s'=>'није успело рашчлањивање датотеке _manifest.json: %s','_manifest.json has an unexpected structure'=>'Датотека _manifest.json има неочекивану структуру','Could not create the package archive.'=>'Није могуће направити архиву пакета.','No writable temporary directory is available for packaging.'=>'Није доступан привремени директоријум са дозволом писања за паковање.','A file in the component could not be read, so it was not packaged.'=>'Датотека у компоненти није могла бити прочитана, па није спакована.','Only plugins and themes can be packaged.'=>'Могу се паковати само додаци и теме.','The component\'s main file was not found.'=>'Главна датотека компоненте није пронађена.','The component is not inside the plugins or themes directory.'=>'Компонента није унутар директоријума са додацима или темама.','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim је остао без времена за овај корак и наставиће при следећој провери.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim није могао да потврди овај сајт, па се ништа неће преузимати нити инсталирати док потврда не успе.','Registration response was missing required fields.'=>'У одговору на регистрацију недостају обавезна поља.','No pending challenge to verify.'=>'Нема изазова на чекању за потврду.','Verify response was missing site_token.'=>'У одговору на потврду недостаје site_token.','No site id is on file to rotate a token for.'=>'Није сачуван ID сајта за који би се ротирао токен.','Rotate-token response was missing site_token.'=>'У одговору на ротацију токена недостаје site_token.','nonce must be a hexadecimal string.'=>'nonce мора бити хексадецимални низ.','No pending challenge for this nonce.'=>'Нема изазова на чекању за овај nonce.','Too many requests.'=>'Превише захтева.','The service asked this site to wait before syncing again.'=>'Услуга је затражила да овај сајт сачека пре следеће синхронизације.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Овај сајт има %1$d компоненти на %2$d језика, што захтева %3$d пакета провере; Babilim може да обради највише %4$d по покретању. Смањите број управљаних језика у Подешавањима или деактивирајте некоришћене додатке и теме, а затим одмах притисните Провери поново.','Babilim could not finish checking this site.'=>'Babilim није могао да заврши проверу овог сајта.','This site\'s address is too long for Babilim to register.'=>'Адреса овог сајта је предугачка да би је Babilim регистровао.','This site\'s locale code is not one Babilim can register.'=>'Кôд локалитета овог сајта није један од оних које Babilim може да региструје.','The download response was missing a usable location.'=>'У одговору на преузимање недостаје употребљива локација.','The service\'s upload offer was incomplete.'=>'Понуда услуге за отпремање била је непотпуна.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Ова компонента је већа него што услуга прихвата, па се не може отпремити.','The packaged component could not be read.'=>'Спакована компонента није могла бити прочитана.','A part of the upload kept failing, so the upload was cancelled.'=>'Један део отпремања је стално грешио, па је отпремање отказано.','Could not read: %s'=>'Није могуће прочитати: %s']];